import Link from "next/link";
import { Button } from "./button";
import { motion } from "motion/react"

interface Items {
    href: string;
    name: string;
}

interface MenuProps {
  items: Items[];
}

export default function Menu({ items }: MenuProps) {
  return (
    <div className="flex flex-row gap-12">
        {items.map((item) => (
          <motion.button key={item.name} initial ={{scale:1.0}} whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }}>
              <h1>{item.name}</h1>
            </motion.button>
        ))}
    </div>
  );
}